def solve():
    input_lines = input()
    t = int(input_lines[0].strip())
    output = []

    for i in range(1, t+1):
        n, k, x = map(int, input_lines[i].strip().split())
        if x == 1:
            if n % 2 == 0 and k >= 2:
                output.append("YES")
                output.append(str(n // 2))
                output.append("2 " * (n // 2))
            else:
                output.append("NO")
        else:
            if n < x:
                output.append("NO")
            else:
                output.append("YES")
                count = 0
                for j in range(1, k+1):
                    if j!= x:
                        count += (n // j) * j
                        n %= j
                if n!= 0:
                    if x!= 1:
                        n -= (x - 1)
                        count += x - 1
                output.append(str(count))
                ans = []
                for j in range(1, k+1):
                    if j!= x:
                        ans.extend([j] * (count // j))
                        count %= j
                if x!= 1:
                    ans.append(x -\n -\1))
                output.append(" ".join(map(str, ans)))

    sys.stdout.write("\n".join(output))

