def solve():
    s = input().strip()
    pattern = re.compile(r'\^\^*|_\^*_\^*')
    subs = [x.group() for x in pattern.finditer(s)]
    if not subs:
        return len(s) - 1
    if s.startswith('^') and len(subs) == 1 and s.endswith(subs):
        return 0
    start = 0
    end = 0
    if s.startswith('_'):
        start = 1
    if s.endswith('^'):
        end = 1
    return start + end + len([x for x in subs if (x!= s[max(start, len(s) - len(subs) - end + 1)] or x!= s[max(start, len(s) - len(subs) - end + len(subs) - 1]]))

