        binaryMatrix = [[0 for i in range(bitLength)]*n
        for i in range(n):
            current = a[i]
            for j in range(bitLength):
                binaryMatrix[i][bitLength-j-1] = current % 2
                current = current//2
        answer = -sys.maxsize
        for i in range(bitLength):
            oneCounter = 0
            zeroCounter = 0
            for j in range(n):
                if binaryMatrix[j][i]:
                    oneCounter += 1
                else:
                    zeroCounter += 1
            if oneCounter > 0 and zeroCounter > 0:
                answer = max(answer, 2**i)
        answers.append(answer)
    return answers

